check:
{v:'VER',what:'cw-pixdev86g: dump the pixel states strip to local storage (dev only)',
 run:function(){
   if(typeof PXDEV86G==='undefined') return 'no dev flag';
   if(!(window.__deploy&&window.__state&&window.__runPrep&&window.__topClear&&window.__endRaid)) return 'SKIP: no raid';
   var g, saved=false, big, bx, CW=130, CH=110, n=0, hp0, dn0, db0, t0, hx0, GRID=6;
   function slot(fn){
     var cx=(n%GRID)*CW, cy=Math.floor(n/GRID)*CH, id;
     wc.setTransform(1,0,0,1,0,0); wc.globalAlpha=1; wc.fillStyle='#5a5a52'; wc.fillRect(535,420,CW,CH);
     try{ fn(); }catch(e){ bx.fillStyle='#f0f'; bx.fillRect(cx,cy,CW,CH); }
     wc.setTransform(1,0,0,1,0,0); wc.globalAlpha=1;
     id=wc.getImageData(535,420,CW,CH); bx.putImageData(id,cx,cy); n++;
   }
   function dr(s,mode,face){ var j; for(j=0;j<3;j++){ pixFrame(); drawOp(600,500,face||0,0,'#242832',0,0,mode||'',0,s); } }
   function hero(o){ var s={hero:1,own:g.player,team:'ally',moving:false,sprint:false,ads:false,hurt:0,bulk:0,rl:0}, z; for(z in o) s[z]=o[z]; return s; }
   function bot(o,ex){ var w={kind:'raider',x:600,y:500,hp:50,wep:{id:'rifle'},state:'idle',r:11}, z, s; for(z in ex) w[z]=ex[z]; s={own:w,team:'foe',merc:0,moving:false,sprint:false,ads:false,hurt:0,bulk:0,rl:0}; for(z in o) s[z]=o[z]; return s; }
   try{
     __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
     CFG.xfPix=1;
     __deploy({kit:[],safe:null,mapIx:0,seed:4242}); keys={}; g=__state();
     if(!g||g.over) return 'SKIP: no raid';
     wc.save(); saved=true;
     big=document.createElement('canvas'); big.width=CW*GRID; big.height=CH*3; bx=big.getContext('2d');
     hp0=g.player.hp; dn0=g.player.downed; db0=g.deathBeat; t0=g.t; hx0=g.player.hitDX; g.player.hitDX=1;
     slot(function(){ dr(hero({}),'',0); });
     slot(function(){ dr(hero({hurt:0.4}),'',0); });
     slot(function(){ dr(hero({hurt:0.3}),'',0); });
     g.player.hp=20;
     slot(function(){ g.t=0; dr(hero({}),'',0); });
     slot(function(){ g.t=0.5; dr(hero({}),'',0); });
     g.player.hp=hp0; g.t=0;
     slot(function(){ g.player.downed=true; g.t=0.1; dr(hero({}),'down',0); g.player.downed=dn0; });
     g.player.hp=0;
     slot(function(){ g.deathBeat=1.5; dr(hero({}),'down',0); });
     slot(function(){ g.deathBeat=1.5-0.11; dr(hero({}),'down',0); });
     slot(function(){ g.deathBeat=1.5-0.2; dr(hero({}),'down',0); });
     slot(function(){ g.deathBeat=1.5-0.5; dr(hero({}),'down',0); });
     g.player.hp=hp0; g.deathBeat=db0;
     slot(function(){ dr(bot({}),'',Math.PI); });
     slot(function(){ var j; for(j=0;j<3;j++){ pixFrame(); raiderFallDraw({op:bot({}).own,x:600,y:500,sg:1},0.1); } });
     slot(function(){ dr(bot({bulk:1}),'',0); });
     slot(function(){ dr(bot({bulk:2}),'',0); });
     slot(function(){ dr(bot({bulk:3}),'',0); });
     slot(function(){ g.t=0.2; dr(bot({},{golden:1}),'',0); });
     slot(function(){ g.t=0.6; var j; for(j=0;j<3;j++){ pixFrame(); pxEliteRing({x:600,y:500,r:11}); } dr(bot({}),'',0); });
     slot(function(){ dr(bot({tell:0.3}),'',0); });
     try{ localStorage.setItem('pixdev'+Date.now(),big.toDataURL('image/png')); }catch(_ls){ return 'dev: no local storage '+_ls; }
     return null;
   }catch(err){ return 'dev threw: '+(err&&err.message||err); }
   finally{
     try{ if(g&&g.player){ g.player.hp=hp0; g.player.downed=dn0; g.deathBeat=db0; g.t=t0; g.player.hitDX=hx0; } }catch(_p){}
     if(saved){ try{ wc.restore(); }catch(_r){} }
     CFG.xfPix=0;
     try{ if(__state()&&!__state().over) __endRaid('abandon'); }catch(_e2){}
     keys={}; __resetCfg(); __topClear(); __cleanProfile();
   }
 }},
